import{_ as t,o as a,c as d,a2 as s}from"./chunks/framework.Dp0m3YJZ.js";const m=JSON.parse('{"title":"06 · 實體頁與 Sv39","description":"","frontmatter":{},"headers":[],"relativePath":"topics/memory.md","filePath":"topics/memory.md","lastUpdated":null}'),r={name:"topics/memory.md"};function o(i,e,n,p,l,c){return a(),d("div",null,[...e[0]||(e[0]=[s(`<h1 id="_06-·-實體頁與-sv39" tabindex="-1">06 · 實體頁與 Sv39 <a class="header-anchor" href="#_06-·-實體頁與-sv39" aria-label="Permalink to &quot;06 · 實體頁與 Sv39&quot;">​</a></h1><p>使用者程式看到的位址，不必等於資料真正所在的 RAM 位址。Page table（分頁表）讓 CPU 轉換位址，也決定能不能讀、寫與執行。</p><h2 id="三級表如何查找" tabindex="-1">三級表如何查找 <a class="header-anchor" href="#三級表如何查找" aria-label="Permalink to &quot;三級表如何查找&quot;">​</a></h2><p>WUWAOS 使用 RISC-V Sv39（39-bit 虛擬位址分頁模式），以 4 KiB 為一頁：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>虛擬位址：L2 索引 9 bits | L1 索引 9 bits | L0 索引 9 bits | 頁內位移 12 bits</span></span>
<span class="line"><span>           根表            下一層表         最後一層表        頁內第幾個 byte</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>每張表 4096 bytes，每個 PTE（分頁表項）8 bytes，所以有 512 個條目；9 bits 正好可選 0–511。前兩層找到下一張表，最後的有效葉節點指向實體頁框。</p><p><code>kernel/vm.c</code> 的 <code>vm_walk</code> 在各層用 <code>(address &gt;&gt; (12 + 9 * level)) &amp; 511</code> 取得索引。實作只使用 4 KiB 映射，沒有大頁。</p><h2 id="配置實體頁" tabindex="-1">配置實體頁 <a class="header-anchor" href="#配置實體頁" aria-label="Permalink to &quot;配置實體頁&quot;">​</a></h2><p><code>kernel/page.c</code> 將核心結尾至 FDT 之前的整頁串成 Free list（空閒串列），排除韌體、核心、固定堆疊與頂端保留區。</p><p>配置時取串列頭，標記 allocated bitmap（已配置位元圖），清零 4096 bytes 後回傳位址。回收檢查範圍、對齊與重複釋放，再放回串列頭。串列操作 O(1)，清零成本與頁大小成正比。</p><p>它回答「哪個空閒實體頁可以給我」，不決定頁框不足時要淘汰誰；後者屬於 VM 的置換政策。</p><h2 id="使用者位址配置" tabindex="-1">使用者位址配置 <a class="header-anchor" href="#使用者位址配置" aria-label="Permalink to &quot;使用者位址配置&quot;">​</a></h2><table tabindex="0"><thead><tr><th>區域</th><th>虛擬範圍</th><th>權限</th></tr></thead><tbody><tr><td>程式碼與唯讀資料</td><td>0x400000–0x404000</td><td>RXU（可讀、可執行、使用者可存取）</td></tr><tr><td>可寫資料</td><td>0x404000–0x405000</td><td>RWU（可讀寫、使用者可存取）</td></tr><tr><td>使用者堆疊</td><td>0x800000–0x801000</td><td>RWU</td></tr><tr><td>Heap（動態資料區）</td><td>0x1000000 起，最多 1 MiB</td><td>sbrk 保留後可按需讀寫</td></tr></tbody></table><p>每個行程有私有頁表與使用者頁。核心與裝置映射可共用，但沒有 U 權限，使用者不能直接存取。RISC-V 這裡採分頁，沒有加入 IA-32 圖中的 segmentation（分段）單元。</p><h2 id="權限與核心複製" tabindex="-1">權限與核心複製 <a class="header-anchor" href="#權限與核心複製" aria-label="Permalink to &quot;權限與核心複製&quot;">​</a></h2><p>CPU 依 PTE 檢查指令／資料存取。核心替使用者搬資料時，也要先檢查合法範圍，再由 <code>user_copy_from</code>／<code>user_copy_to</code> 逐頁載入與複製，不能信任使用者傳來的任意位址。</p><p>映射改變後以 sfence.vma（分頁轉譯同步指令）使舊轉譯失效；不能在 CPU 仍可能使用舊轉譯時把頁框交給別人。</p><h2 id="在-qemu-觀察" tabindex="-1">在 QEMU 觀察 <a class="header-anchor" href="#在-qemu-觀察" aria-label="Permalink to &quot;在 QEMU 觀察&quot;">​</a></h2><p>執行 <code>ps</code> 看底層可配置頁數，再執行 <code>vmstat</code> 看使用者常駐頁。QEMU RAM 仍是 128 MiB，但核心、頁表與保留區會占用一部分；兩份統計的範圍不同。</p><p>目前建立行程不預先填滿所有使用者頁，下一章說明<a href="./paging.html">按需分頁</a>。觀念參考：<code>notes/ch9 Main Memory.md</code> 的分頁與位址轉換。早期動態配置驗收在 <a href="./../SPEC-08-memory.html">Spec 08</a>，載入時機以 <a href="./../SPEC-10-demand-paging.html">Spec 10</a> 為準。</p>`,20)])])}const b=t(r,[["render",o]]);export{m as __pageData,b as default};
